def test_function_hashes_match_live_evidence():
    assert p.function_span(FIXTURES["konteyner"], "konteyner.py", "gde_mashina")
    assert p.function_span(FIXTURES["konteyner"], "konteyner.py", "_ekran")
    assert p.function_span(FIXTURES["cars_ui"], "cars_ui.py", "stage_menu")
    assert p.function_span(FIXTURES["cars_ui"], "cars_ui.py", "toggle_publish")
    assert p.function_span(FIXTURES["seo"], "stranica.py", "_ua_seo068_normalize")
    assert p.function_span(FIXTURES["pub"], "publikaciya.py", "opublikovat")
    assert p.function_span(FIXTURES["pub"], "publikaciya.py", "_otkat")

def test_exact_transforms_compile_and_keep_handler_contracts():
    k=p.patch_konteyner(FIXTURES["konteyner"], False)
    assert 'code not in ("sea_loaded", "sea_transit")' in k
    assert k.count('car_setstage:%d:sea_loaded') == 1
    c=p.patch_cars_ui(FIXTURES["cars_ui"], False)
    assert 'async def toggle_publish(update: Update, context: ContextTypes.DEFAULT_TYPE):' in c
    assert 'if _ok_rem2 is not True:' in c
    s=p.patch_seo_module("stranica.py", FIXTURES["seo"], False)
    assert 'SEO068_DIAGNOSTIC_TARGET_MISSING' not in s
    u=p.patch_publikaciya(FIXTURES["pub"], False)
    assert '_master(kod)' in u and '_ua9_sobrat_katalog()' in u
    assert '_postroit_stranicu' not in u

